class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1
        cnt = [0] * 32
        for x in nums:
            cnt[x.bit_length() - 1] += 1
        ans = 0
        for b in range(31):
            if target >> b & 1:
                if cnt[b] == 0:
                    j = b
                    while cnt[j] == 0:
                        j += 1
                    ans += j - b
                    cnt[j] -= 1
                    for t in range(b, j):
                        cnt[t] += 2
                cnt[b] -= 1
            cnt[b + 1] += cnt[b] // 2
        return ans

