class Solution {
public:
    int minOperations(vector<int>& nums, int target) {
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        if (total < target) return -1;
        long long cnt[33] = {};
        for (int x : nums) cnt[__builtin_ctz(x)]++;
        long long ans = 0;
        for (int b = 0; b < 31; ++b) {
            if (target >> b & 1) {
                if (!cnt[b]) {
                    int j = b;
                    while (!cnt[j]) j++;
                    ans += j - b;
                    cnt[j]--;
                    for (int t = b; t < j; ++t) cnt[t] += 2;
                }
                cnt[b]--;
            }
            cnt[b + 1] += cnt[b] / 2;
        }
        return ans;
    }
};

