class Solution {
    public int minOperations(List<Integer> nums, int target) {
        long total = 0;
        for (int x : nums) total += x;
        if (total < target) return -1;
        long[] cnt = new long[33];
        for (int x : nums) cnt[Integer.numberOfTrailingZeros(x)]++;
        long ans = 0;
        for (int b = 0; b < 31; b++) {
            if ((target >> b & 1) == 1) {
                if (cnt[b] == 0) {
                    int j = b;
                    while (cnt[j] == 0) j++;
                    ans += j - b;
                    cnt[j]--;
                    for (int t = b; t < j; t++) cnt[t] += 2;
                }
                cnt[b]--;
            }
            cnt[b + 1] += cnt[b] / 2;
        }
        return (int) ans;
    }
}

