var minOperations = function(nums, target) {
    let total = nums.reduce((a, x) => a + x, 0);
    if (total < target) return -1;
    const cnt = Array(33).fill(0);
    for (const x of nums) cnt[Math.log2(x)]++;
    let ans = 0;
    for (let b = 0; b < 31; b++) {
        if ((target >> b) & 1) {
            if (cnt[b] === 0) {
                let j = b;
                while (cnt[j] === 0) j++;
                ans += j - b;
                cnt[j]--;
                for (let t = b; t < j; t++) cnt[t] += 2;
            }
            cnt[b]--;
        }
        cnt[b + 1] += Math.floor(cnt[b] / 2);
    }
    return ans;
};
